'use strict';

// MODULES //

var tape = require( 'tape' );
var flatten2d = require( '@stdlib/array/base/flatten2d' );
var Float64Array = require( '@stdlib/array/float64' );
var dgetrans = require( './../lib/ndarray.js' );

// HELPERS //

function createMatrix(arr, shape, columnMajor) {
	return new Float64Array(flatten2d(arr, shape, columnMajor));
}

// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof dgetrans, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function has an arity of 10', function test( t ) {
	t.strictEqual( dgetrans.length, 10, 'returns expected value' );
	t.end();
});

// ------------------------------------------------------------------
// Test cases for different shapes and memory layouts
// ------------------------------------------------------------------

tape( 'transposes a tall rectangular matrix (row-major -> row-major)', function test( t ) {
	var M = 4, N = 2;

	var A = createMatrix([
		[1, 2],
		[3, 4],
		[5, 6],
		[7, 8]
	], [M, N], false);

	var out = new Float64Array(M * N);

	var expected = createMatrix([
		[1, 3, 5, 7],
		[2, 4, 6, 8]
	], [N, M], false);

	var actual = dgetrans(M, N, A, N, 1, 0, out, M, 1, 0);

	t.deepEqual(actual, expected, 'returns expected transpose');
	t.end();
});

tape( 'transposes a tall rectangular matrix (row-major -> column-major)', function test( t ) {
	var M = 4, N = 2;

	var A = createMatrix([
		[1, 2],
		[3, 4],
		[5, 6],
		[7, 8]
	], [M, N], false);

	var out = new Float64Array(M * N);

	var expected = createMatrix([
		[1, 3, 5, 7],
		[2, 4, 6, 8]
	], [N, M], true);

	var actual = dgetrans(M, N, A, N, 1, 0, out, 1, N, 0);

	t.deepEqual(actual, expected, 'returns expected transpose');
	t.end();
});

tape( 'transposes a wide rectangular matrix (column-major -> row-major)', function test( t ) {
	var M = 2, N = 4;

	var A = createMatrix([
		[1, 2, 3, 4],
		[5, 6, 7, 8]
	], [M, N], true);

	var out = new Float64Array(M * N);

	var expected = createMatrix([
		[1, 5],
		[2, 6],
		[3, 7],
		[4, 8]
	], [N, M], false);

	var actual = dgetrans(M, N, A, 1, M, 0, out, M, 1, 0);

	t.deepEqual(actual, expected, 'returns expected transpose');
	t.end();
});

tape( 'transposes a square matrix (column-major -> column-major)', function test( t ) {
	var M = 3, N = 3;

	var A = createMatrix([
		[1, 2, 3],
		[4, 5, 6],
		[7, 8, 9]
	], [M, N], true);

	var out = new Float64Array(M * N);

	var expected = createMatrix([
		[1, 4, 7],
		[2, 5, 8],
		[3, 6, 9]
	], [N, M], true);

	var actual = dgetrans(M, N, A, 1, M, 0, out, 1, N, 0);

	t.deepEqual(actual, expected, 'returns expected transpose');
	t.end();
});

tape( 'transposes an empty matrix (M=0)', function test( t ) {
	var M = 0, N = 3;

	var A = new Float64Array(0);
	var out = new Float64Array(0);
	var expected = new Float64Array(0);

	var actual = dgetrans(M, N, A, 1, M, 0, out, 1, N, 0);

	t.deepEqual(actual, expected, 'returns empty transpose');
	t.end();
});

tape( 'transposes an empty matrix (N=0)', function test( t ) {
	var M = 3, N = 0;

	var A = new Float64Array(0);
	var out = new Float64Array(0);
	var expected = new Float64Array(0);

	var actual = dgetrans(M, N, A, 1, M, 0, out, 1, N, 0);

	t.deepEqual(actual, expected, 'returns empty transpose');
	t.end();
});

tape( 'transposes a single element matrix', function test( t ) {
	var M = 1, N = 1;

	var A = new Float64Array([42]);
	var out = new Float64Array(1);

	var expected = new Float64Array([42]);

	var actual = dgetrans(M, N, A, 1, M, 0, out, 1, N, 0);

	t.deepEqual(actual, expected, 'returns expected transpose');
	t.end();
});

